CREATE TABLE public.mural_leituras (post_id uuid NOT NULL REFERENCES public.mural_posts(id) ON DELETE CASCADE, usuario_id uuid NOT NULL DEFAULT auth.uid(), lido_em timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(post_id,usuario_id));
GRANT SELECT ON public.mural_leituras TO authenticated;
GRANT ALL ON public.mural_leituras TO service_role;
ALTER TABLE public.mural_leituras ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Consulta propria leitura mural" ON public.mural_leituras FOR SELECT TO authenticated USING (usuario_id=auth.uid() AND public.is_active_user(auth.uid()));
CREATE OR REPLACE FUNCTION public.notificacoes_mural() RETURNS TABLE(id uuid,titulo text,mensagem text,perfil_nome text,publicar_em timestamptz,expira_em timestamptz,editado_em timestamptz,lido boolean,tipo text,exige_confirmacao boolean,confirmado_em timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.titulo,''::text,CASE WHEN p.tipo='aniversario' THEN 'Aniversário' ELSE 'Tempo de casa' END,p.criado_em,(public.primeiro_util_mes((p.data_post+interval '1 month')::date)::timestamp AT TIME ZONE 'America/Sao_Paulo'),null::timestamptz,EXISTS(SELECT 1 FROM public.mural_leituras l WHERE l.post_id=p.id AND l.usuario_id=auth.uid()) OR p.criado_em<=coalesce((SELECT primeiro_acesso FROM public.profiles WHERE id=auth.uid()),'-infinity'::timestamptz),'mural'::text,false,null::timestamptz FROM public.mural_posts p WHERE public.is_active_user(auth.uid()) AND p.tipo IN ('aniversario','tempo_casa') AND public.mural_post_vigente(p.data_post,(now() AT TIME ZONE 'America/Sao_Paulo')::date) $$;
CREATE OR REPLACE FUNCTION public.listar_notificacoes(_so_nao_lidos boolean DEFAULT false,_limite integer DEFAULT 20,_deslocamento integer DEFAULT 0,_so_obrigatorios boolean DEFAULT false,_aviso_id uuid DEFAULT null,_priorizar boolean DEFAULT false) RETURNS TABLE(id uuid,titulo text,mensagem text,perfil_nome text,publicar_em timestamptz,expira_em timestamptz,editado_em timestamptz,lido boolean,tipo text,exige_confirmacao boolean,confirmado_em timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH avisos AS (SELECT a.id,a.titulo,a.mensagem,p.nome,a.publicar_em,a.expira_em,a.editado_em,CASE WHEN a.exige_confirmacao THEN c.confirmado_em IS NOT NULL ELSE a.publicar_em<=coalesce((SELECT primeiro_acesso FROM public.profiles WHERE id=auth.uid()),'-infinity'::timestamptz) OR EXISTS(SELECT 1 FROM public.avisos_leituras l WHERE l.aviso_id=a.id AND l.usuario_id=auth.uid()) END AS lido,a.tipo,a.exige_confirmacao,c.confirmado_em FROM public.avisos a JOIN public.perfis p ON p.id=a.perfil_id LEFT JOIN public.avisos_confirmacoes c ON c.aviso_id=a.id AND c.usuario_id=auth.uid() WHERE public.aviso_disponivel(a.id)), v AS (SELECT * FROM avisos UNION ALL SELECT * FROM public.notificacoes_mural()) SELECT * FROM v WHERE (NOT _so_nao_lidos OR NOT v.lido) AND (NOT _so_obrigatorios OR v.exige_confirmacao) AND (_aviso_id IS NULL OR v.id=_aviso_id) ORDER BY CASE WHEN _priorizar THEN v.exige_confirmacao AND NOT v.lido ELSE false END DESC,v.publicar_em DESC,v.id LIMIT least(greatest(_limite,1),100) OFFSET greatest(_deslocamento,0) $$;
CREATE OR REPLACE FUNCTION public.contar_notificacoes() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.contar_nao_lidos()+(SELECT count(*)::integer FROM public.notificacoes_mural() WHERE NOT lido) $$;
CREATE OR REPLACE FUNCTION public.marcar_mural_lido(_post_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.notificacoes_mural() WHERE id=_post_id) THEN RAISE EXCEPTION 'Comemoração indisponível'; END IF; INSERT INTO public.mural_leituras(post_id,usuario_id) VALUES(_post_id,auth.uid()) ON CONFLICT DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.marcar_todas_notificacoes_lidas() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; m integer; BEGIN IF NOT public.is_active_user(auth.uid()) THEN RETURN 0; END IF; n:=public.marcar_todos_avisos_lidos(); INSERT INTO public.mural_leituras(post_id,usuario_id) SELECT id,auth.uid() FROM public.notificacoes_mural() ON CONFLICT DO NOTHING; GET DIAGNOSTICS m=ROW_COUNT; RETURN n+m; END $$;
REVOKE ALL ON FUNCTION public.notificacoes_mural(),public.listar_notificacoes(boolean,integer,integer,boolean,uuid,boolean),public.contar_notificacoes(),public.marcar_mural_lido(uuid),public.marcar_todas_notificacoes_lidas() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.notificacoes_mural(),public.listar_notificacoes(boolean,integer,integer,boolean,uuid,boolean),public.contar_notificacoes(),public.marcar_mural_lido(uuid),public.marcar_todas_notificacoes_lidas() TO authenticated;
ALTER TABLE public.reward_programs ADD COLUMN website text, ADD COLUMN materials_url text;